const bunMode = document.body.dataset.game === 'buns';
const field = document.querySelector('#field');
const ctx = field.getContext('2d');
const startButton = document.querySelector('#start');
const stopButton = document.querySelector('#stop');
const scoreOutput = document.querySelector('#score');
const timeOutput = document.querySelector('#time');
const result = document.querySelector('#result');
const width = 400;
const height = 360;
const duration = 30;
const difficultyButtons = document.querySelectorAll('[data-level]');
let selectedLevel = 'easy';
const levels = {
  'super-easy': { speed: 85, acceleration: 1, interval: .95 },
  easy: { speed: 123, acceleration: 2.6, interval: .75 },
  medium: { speed: 160, acceleration: 3, interval: .64 },
  hard: { speed: 220, acceleration: 4, interval: .52 },
  impossible: { speed: 330, acceleration: 5, interval: .36 },
};
let level = levels.easy;
difficultyButtons.forEach(button => button.addEventListener('click', () => {
  selectedLevel = button.dataset.level;
  gameScores.showLevel(selectedLevel);
  difficultyButtons.forEach(choice => {
    choice.setAttribute('aria-pressed', String(choice.dataset.level === selectedLevel));
  });
}));
const squirrelSize = 140;
const musicButton = document.querySelector('#music');
const volume = document.querySelector('#volume');
const music = new Audio('data:audio/mpeg;base64,');
music.loop = true;
music.volume = Number(volume.value) / 100 * .5;
let musicEnabled = true;

function playMusic() {
  if (musicEnabled) music.play().catch(() => {});
}
let language = 'en';
const L = (en, ja) => language === 'ja' ? ja : en;
momoLanguage.subscribe(code => {
  language = code;
  musicButton.textContent = musicEnabled ? L('Music on', 'おと ON') : L('Music off', 'おと OFF');
});
musicButton.addEventListener('click', () => {
  musicEnabled = !musicEnabled;
  musicButton.textContent = musicEnabled ? L('Music on', 'おと ON') : L('Music off', 'おと OFF');
  musicButton.setAttribute('aria-pressed', String(musicEnabled));
  if (!musicEnabled) music.pause();
  else if (startTime !== null) playMusic();
});
volume.addEventListener('input', () => {
  music.volume = Number(volume.value) / 100 * .5;
});
const keys = new Set();
const squirrel = new Image();
let held = 0;
let player = width / 2;
let fries = [];
let catches = [];
const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
let score = 0;
let startTime = null;
let previous = 0;
let nextSpawn = 0;
let dragId = null;
let axisX = 1;
let axisY = 1;

function move(position) {
  player = Math.max(squirrelSize * .38, Math.min(width - squirrelSize * .38, position));
}

function drawBun(bun) {
  ctx.save();
  ctx.translate(bun.x, bun.y);
  ctx.rotate(bun.tilt * .5);
  ctx.scale(axisY / axisX, 1);
  const dough = ctx.createLinearGradient(0, -18, 0, 15);
  dough.addColorStop(0, bun.smiles ? '#fff9e8' : '#f9c7ed');
  dough.addColorStop(1, bun.smiles ? '#f0ca9e' : '#be79b4');
  ctx.fillStyle = dough;
  ctx.strokeStyle = '#a66951';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(0, -16);
  ctx.bezierCurveTo(-9, -17, -24, -6, -23, 5);
  ctx.bezierCurveTo(-22, 19, 22, 19, 23, 5);
  ctx.bezierCurveTo(24, -6, 9, -17, 0, -16);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(-6, -14);
  ctx.quadraticCurveTo(-10, -9, -13, -8);
  ctx.moveTo(0, -15);
  ctx.quadraticCurveTo(4, -11, 3, -8);
  ctx.moveTo(6, -14);
  ctx.quadraticCurveTo(12, -12, 14, -7);
  ctx.stroke();
  if (bun.smiles) {
    ctx.fillStyle = '#502c42';
    for (const eye of [-7, 7]) {
      ctx.beginPath();
      ctx.arc(eye, 1, 2, 0, 2 * Math.PI);
      ctx.fill();
    }
    ctx.beginPath();
    ctx.arc(0, 3, 4, 0, Math.PI);
    ctx.stroke();
    ctx.fillStyle = '#ed9fa9';
    ctx.fillRect(-14, 5, 5, 2);
    ctx.fillRect(9, 5, 5, 2);
  } else {
    ctx.fillStyle = '#85457f';
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(side * 10, -12);
      ctx.lineTo(side * 17, -25);
      ctx.quadraticCurveTo(side * 22, -20, side * 20, -7);
      ctx.fill();
    }
    ctx.fillStyle = '#502c42';
    ctx.fillRect(-9, 1, 5, 3);
    ctx.fillRect(4, 1, 5, 3);
  }
  ctx.restore();
}

function drawFry(fry) {
  ctx.save();
  ctx.translate(fry.x, fry.y);
  ctx.rotate(fry.tilt);
  ctx.scale(axisY / axisX, fry.stretch);
  const crust = ctx.createLinearGradient(-8, 0, 8, 0);
  crust.addColorStop(0, '#ffe38a');
  crust.addColorStop(.48, '#ffcc51');
  crust.addColorStop(1, '#cf710f');
  ctx.fillStyle = crust;
  ctx.strokeStyle = '#a7521d';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-6, -17);
  ctx.quadraticCurveTo(0, -20, 6, -17);
  for (let y = -17; y < 15; y += 8) {
    ctx.quadraticCurveTo(10, y + 2, 6, y + 4);
    ctx.quadraticCurveTo(3, y + 6, 6, y + 8);
  }
  ctx.quadraticCurveTo(7, 20, -6, 17);
  ctx.lineTo(-6, 15);
  for (let y = 15; y > -17; y -= 8) {
    ctx.quadraticCurveTo(-3, y - 2, -6, y - 4);
    ctx.quadraticCurveTo(-10, y - 6, -6, y - 8);
  }
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.strokeStyle = '#fff0b8';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(-3, -14);
  for (let y = -14; y < 10; y += 8) {
    ctx.bezierCurveTo(-.5, y + 2, -5, y + 6, -3, y + 8);
  }
  ctx.stroke();
  ctx.restore();
}

const cupHalfWidth = 30;
const cupMouthY = 293;

function crossesCup(fry, previousY, previousPlayer) {
  if (previousY >= cupMouthY || fry.y < cupMouthY) return false;
  const progress = (cupMouthY - previousY) / (fry.y - previousY);
  const center = previousPlayer + (player - previousPlayer) * progress;
  return Math.abs(fry.x - center) <= cupHalfWidth * axisY / axisX;
}

function drawCup(now) {
  ctx.save();
  ctx.translate(player, cupMouthY);
  ctx.scale(axisY / axisX, 1);

  ctx.fillStyle = '#7f2438';
  ctx.beginPath();
  ctx.ellipse(0, 0, cupHalfWidth, 8, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  for (const effect of catches) {
    if (!effect.fry || reducedMotion.matches) continue;
    const progress = Math.max(0, (now - effect.at) / 135);
    if (progress >= 1) continue;
    drawFry({
      ...effect.fry,
      x: player + effect.offset * (1 - progress),
      y: cupMouthY + 27 * progress,
      stretch: effect.fry.stretch * (1 - progress),
    });
  }

  ctx.save();
  ctx.translate(player, cupMouthY);
  ctx.scale(axisY / axisX, 1);
  const paper = ctx.createLinearGradient(-30, 0, 30, 32);
  paper.addColorStop(0, '#f45e6b');
  paper.addColorStop(1, '#ce324f');
  ctx.beginPath();
  ctx.moveTo(-cupHalfWidth, 0);
  ctx.quadraticCurveTo(0, 13, cupHalfWidth, 0);
  ctx.lineTo(23, 32);
  ctx.quadraticCurveTo(0, 39, -23, 32);
  ctx.closePath();
  ctx.fillStyle = paper;
  ctx.fill();
  ctx.lineWidth = 1.5;
  ctx.strokeStyle = '#a82b48';
  ctx.stroke();

  ctx.fillStyle = '#ffe6a3';
  for (let row = 0; row < 2; row++) {
    for (let column = 0; column < 8; column++) {
      if ((row + column) % 2 === 0) ctx.fillRect(-20 + column * 5, 23 + row * 5, 5, 5);
    }
  }
  ctx.restore();
}

function draw() {
  const rect = field.getBoundingClientRect();
  const density = window.devicePixelRatio || 1;
  const pixelWidth = Math.max(1, Math.round(rect.width * density));
  const pixelHeight = Math.max(1, Math.round(rect.height * density));
  if (field.width !== pixelWidth) field.width = pixelWidth;
  if (field.height !== pixelHeight) field.height = pixelHeight;
  ctx.setTransform(pixelWidth / width, 0, 0, pixelHeight / height, 0, 0);
  axisX = pixelWidth / width;
  axisY = pixelHeight / height;
  ctx.fillStyle = bunMode ? '#fff1db' : '#ffe5ef';
  ctx.fillRect(0, 0, width, height);
  ctx.fillStyle = bunMode ? '#f6c989' : '#fff6fa';
  for (let y = 18; y < height; y += 32) {
    for (let x = 16; x < width; x += 32) {
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.fillStyle = bunMode ? '#f7d9b4' : '#efd0fb';
  ctx.fillRect(0, 326, width, 34);
  for (const fry of fries) {
    if (bunMode) {
      drawBun(fry);
      continue;
    }
    drawFry(fry);
  }
  if (squirrel.complete && squirrel.naturalWidth) {
    const latest = catches.at(-1);
    const age = latest ? performance.now() - latest.at : Infinity;
    const shake = !reducedMotion.matches && latest?.label === '−1' && age < 260
      ? Math.sin(age / 12) * 5 * (1 - age / 260) : 0;
    const hop = !reducedMotion.matches && latest?.label !== '−1' && age < 260 ? Math.sin(Math.PI * age / 260) * 14 : 0;
    // The canvas fills a responsive rectangle, so its two axes may scale differently.
    const size = squirrelSize * Math.min(axisX, axisY);
    const spriteWidth = size / axisX;
    const spriteHeight = size / axisY;
    ctx.drawImage(squirrel, player + shake - spriteWidth / 2, 334 - spriteHeight - (bunMode ? hop : 0), spriteWidth, spriteHeight);
  }
  const now = performance.now();
  catches = catches.filter(catchEffect => now - catchEffect.at < 600);
  if (!bunMode) drawCup(now);
  for (const effect of catches) {
    const progress = Math.max(0, (now - effect.at) / 600);
    const spread = reducedMotion.matches ? 0 : 35 * progress;
    ctx.save();
    ctx.setTransform(axisY, 0, 0, axisY, 0, 0);
    ctx.globalAlpha = 1 - progress;
    ctx.textAlign = 'center';
    const handwriting = getComputedStyle(document.documentElement).getPropertyValue('--game-handwriting');
    ctx.font = 'bold 25px ' + handwriting.trim();
    ctx.lineWidth = 4;
    ctx.strokeStyle = '#fff';
    ctx.fillStyle = '#a7195b';
    const labelY = bunMode ? 199 : cupMouthY - 30;
    ctx.strokeText(effect.label, effect.x * axisX / axisY, labelY - spread);
    ctx.fillText(effect.label, effect.x * axisX / axisY, labelY - spread);
    if (effect.label === "+1" && !reducedMotion.matches) {
      ctx.fillStyle = '#d98711';
      ctx.font = '19px sans-serif';
      ctx.fillText('✦', (effect.x - 19 - spread / 2) * axisX / axisY, labelY + 9 - spread);
      ctx.fillText('✧', (effect.x + 20 + spread / 2) * axisX / axisY, labelY + 4 - spread / 2);
    }
    ctx.restore();
  }
}

let practicing = false;
let practiced = false;

function step(now) {
  if (startTime === null) return;
  const elapsed = practicing ? 0 : (now - startTime) / 1000;
  const dt = Math.min(.05, (now - previous) / 1000);
  previous = now;
  timeOutput.value = Math.max(0, Math.ceil(duration - elapsed));
  if (elapsed >= duration) {
    finishGame(true);
    return;
  }
  const direction = Number(keys.has('ArrowRight')) - Number(keys.has('ArrowLeft'));
  const previousPlayer = player;
  move(player + (held || direction) * 270 * dt);
  if (practicing && fries.length === 0) {
    fries.push({ x: width / 2, y: 80, tilt: .15, stretch: 1, smiles: true });
  } else if (!practicing && elapsed >= nextSpawn) {
    fries.push({ x: 22 + Math.random() * (width - 44), y: -14, tilt: Math.random() - .5, stretch: .8 + Math.random() * .4, smiles: !bunMode || Math.random() < .67 });
    nextSpawn = elapsed + Math.max(level.interval * .55, level.interval - elapsed / 90);
  }
  fries = fries.filter(fry => {
    const previousY = fry.y;
    fry.y += (practicing ? 95 : level.speed + elapsed * level.acceleration) * dt;
    const caught = bunMode
      ? fry.y >= 278 && fry.y <= 329 && Math.abs(player - fry.x) < squirrelSize * .39
      : crossesCup(fry, previousY, previousPlayer);
    if (caught) {
      const effect = { x: player, at: now };
      if (!bunMode) {
        effect.fry = fry;
        const halfWidth = cupHalfWidth * axisY / axisX;
        effect.offset = Math.max(-halfWidth, Math.min(halfWidth, fry.x - player));
      }
      if (practicing) {
        practicing = false;
        practiced = true;
        startTime = now;
        result.textContent = L('You got it! Go!', 'つかまえた！ そのちょうし！');
        catches.push({ ...effect, label: '✓' });
        return false;
      }
      score += fry.smiles ? 1 : -1;
      scoreOutput.value = score;
      catches.push({ ...effect, label: fry.smiles ? '+1' : '−1' });
      return false;
    }
    return fry.y < (bunMode ? 332 : height + 23);
  });
  draw();
  requestAnimationFrame(step);
}

function finishGame(completed = false) {
  startTime = null;
  practicing = false;
  music.pause();
  catches = [];
  startButton.disabled = false;
  stopButton.hidden = true;
  difficultyButtons.forEach(button => { button.disabled = false; });
  startButton.textContent = L('Play again', 'もういちど');
  gameScores.finish(score, completed);
  result.textContent = bunMode ? L('Final score: ', 'スコア：') + score : L('You caught ' + score + (score === 1 ? ' fry!' : ' fries!'), 'フライを ' + score + 'こ つかまえた！');
  draw();
}
stopButton.addEventListener('click', () => {
  if (startTime !== null) finishGame();
});

startButton.addEventListener('click', () => {
  gameScores.start(selectedLevel);
  practicing = !bunMode && !practiced;
  player = width / 2;
  fries = [];
  catches = [];
  scoreOutput.value = score = 0;
  timeOutput.value = duration;
  nextSpawn = 0;
  startTime = previous = performance.now();
  startButton.textContent = L('Playing…', 'プレイ中…');
  startButton.disabled = true;
  stopButton.hidden = false;
  level = levels[selectedLevel];
  difficultyButtons.forEach(button => { button.disabled = true; });
  music.currentTime = 0;
  playMusic();
  result.textContent = bunMode ? L('Catch the smiling buns! Dodge the Devil Buns!', 'にこにこ肉まんを つかまえて！ デビル肉まんは よけて！') : practicing ? L('Catch this fry to start!', 'このフライを つかまえて スタート！') : L('Here come the fries!', 'フライが きたよ！');
  requestAnimationFrame(step);
});

function moveToPointer(event) {
  const rect = field.getBoundingClientRect();
  move((event.clientX - rect.left) / rect.width * width);
  draw();
}
field.addEventListener('pointerdown', event => {
  if (dragId !== null) return;
  dragId = event.pointerId;
  field.setPointerCapture(dragId);
  moveToPointer(event);
});
field.addEventListener('pointermove', event => {
  if (event.pointerId === dragId) moveToPointer(event);
});
field.addEventListener('lostpointercapture', () => { dragId = null; });

for (const [id, direction] of [['left', -1], ['right', 1]]) {
  const button = document.getElementById(id);
  button.addEventListener('pointerdown', event => {
    button.setPointerCapture(event.pointerId);
    held = direction;
    move(player + 15 * direction);
    draw();
  });
  button.addEventListener('lostpointercapture', () => {
    if (held === direction) held = 0;
  });
  button.addEventListener('click', event => {
    if (event.detail !== 0) return;
    move(player + 30 * direction);
    draw();
  });
}
window.addEventListener('keydown', event => {
  if (!['ArrowLeft','ArrowRight'].includes(event.key) || startTime === null) return;
  event.preventDefault();
  keys.add(event.key);
});
window.addEventListener('keyup', event => keys.delete(event.key));
window.addEventListener('blur', () => { keys.clear(); held = 0; });
window.addEventListener('resize', draw);
squirrel.addEventListener('load', draw);
squirrel.src = 'data:image/png;base64,';
draw();
